static int GetBodyGlobalBBox(tag_t bodyTag, double minPt[3], double maxPt[3])
{
    if (bodyTag == NULL_TAG) return 1;
    NXOpen::Body* body = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(bodyTag));
    if (!body) return 1;
    std::vector<NXOpen::Edge*> edges = body->GetEdges();
    if (edges.empty()) return 1;
    minPt[0] = minPt[1] = minPt[2] = 1e308;
    maxPt[0] = maxPt[1] = maxPt[2] = -1e308;
    bool hasPt = false;
    for (NXOpen::Edge* edge : edges) {
        if (!edge) continue;
        NXOpen::Point3d v1, v2; edge->GetVertices(&v1, &v2); NXOpen::Point3d vlist[] = {v1, v2};
        for (const NXOpen::Point3d& v : vlist) {
            hasPt = true;
            if (v.X < minPt[0]) minPt[0] = v.X;
            if (v.Y < minPt[1]) minPt[1] = v.Y;
            if (v.Z < minPt[2]) minPt[2] = v.Z;
            if (v.X > maxPt[0]) maxPt[0] = v.X;
            if (v.Y > maxPt[1]) maxPt[1] = v.Y;
            if (v.Z > maxPt[2]) maxPt[2] = v.Z;
        }
    }
    if (!hasPt) return 1;
    return 0;
}

