// Helper: get first selected object tag
static tag_t GetFirstSelectedTag(NXOpen::BlockStyler::BlockDialog* dialog, const char* blockId)
{
    if (dialog == NULL) return NULL_TAG;
    try {
        PropertyList *selProps = dialog->GetBlockProperties(blockId);
        if (selProps) {
            std::vector<NXOpen::TaggedObject*> objs = selProps->GetTaggedObjectVector("SelectedObjects");
            delete selProps;
            if (!objs.empty() && objs[0] != NULL) return objs[0]->Tag();
        }
    } catch(...) {}
    return NULL_TAG;
}

// Helper: perform move or copy
static bool MoveOrCopyObject(tag_t objTag, const NXOpen::Point3d& srcPt, const NXOpen::Point3d& dstPt, bool copyMode)
{
    if (objTag == NULL_TAG) return false;
    double dx = dstPt.X - srcPt.X, dy = dstPt.Y - srcPt.Y, dz = dstPt.Z - srcPt.Z;
    if (fabs(dx)<1e-6 && fabs(dy)<1e-6 && fabs(dz)<1e-6) return true;
    NXOpen::Part *workPart = moveDlg::theSession->Parts()->Work();
    NXOpen::Features::MoveObjectBuilder *mb = workPart->BaseFeatures()->CreateMoveObjectBuilder(static_cast<NXOpen::Features::MoveObject*>(NULL));
    if (mb == NULL) return false;
    NXOpen::NXObject *nxObj = dynamic_cast<NXOpen::NXObject*>(NXOpen::NXObjectManager::Get(objTag));
    if (nxObj != NULL) {
        try { NXOpen::Features::RemoveParametersBuilder* rp = workPart->Features()->CreateRemoveParametersBuilder(); if (rp) { rp->Objects()->Add(nxObj); rp->Commit(); rp->Destroy(); } } catch(...) {}
        mb->ObjectToMoveObject()->Add(nxObj);
    } else { mb->Destroy(); return false; }
    NXOpen::GeometricUtilities::ModlMotion *m = mb->TransformMotion();
    m->SetOption(NXOpen::GeometricUtilities::ModlMotion::OptionsDeltaXyz);
    m->SetDeltaEnum(NXOpen::GeometricUtilities::ModlMotion::DeltaReferenceWcsWorkPart);
    m->DeltaXc()->SetNumberValue(dx);
    m->DeltaYc()->SetNumberValue(dy);
    m->DeltaZc()->SetNumberValue(dz);
    mb->SetMoveObjectResult(copyMode ? NXOpen::Features::MoveObjectBuilder::MoveObjectResultOptionsCopyOriginal : NXOpen::Features::MoveObjectBuilder::MoveObjectResultOptionsMoveOriginal);
    mb->Commit();
    mb->Destroy();
    return true;
}
static tag_t GetBodyFromSelection(tag_t objTag)
{
    if (objTag == NULL_TAG) return NULL_TAG;
    NXOpen::Body* body = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(objTag));
    if (body) return body->Tag();
    NXOpen::Face* face = dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(objTag));
    if (face) {
        body = face->GetBody();
        if (body) return body->Tag();
    }
    return NULL_TAG;
}

static bool CalculateEnumPoint(tag_t objTag, int enumVal, bool isDest, double pt[3])
{
    pt[0]=pt[1]=pt[2]=0.0;
    if (isDest) {
        // For XO/ZO/YO/ABS/WCS we may need the body's bounding box
        switch (enumVal) {
            case 0: return true; // ABSåŽŸç‚¹ -> (0,0,0)
            case 3: { // WCSåŽŸç‚¹ via NXOpen
                NXOpen::Point3d wcsO = moveDlg::theSession->Parts()->Work()->WCS()->Origin();
                pt[0]=wcsO.X; pt[1]=wcsO.Y; pt[2]=wcsO.Z; return true;
            }
            case 2: case 4: case 6: { // ZOç‚?XOç‚?YOç‚?- use body bbox axis center
                tag_t bodyTag = GetBodyFromSelection(objTag);
                if (bodyTag == NULL_TAG) return false;
                double minPt[3], maxPt[3];
                if (GetBodyGlobalBBox(bodyTag, minPt, maxPt) != 0) return false;
                double cx=(minPt[0]+maxPt[0])/2.0, cy=(minPt[1]+maxPt[1])/2.0, cz=(minPt[2]+maxPt[2])/2.0;
                if (enumVal == 4) { pt[0]=cx; } // XOç‚?-> (cx,0,0)
                else if (enumVal == 6) { pt[1]=cy; } // YOç‚?-> (0,cy,0)
                else { pt[2]=cz; } // ZOç‚?-> (0,0,cz)
                return true;
            }
            case 5: case 1: break; // ä½“ä¸­å¿?é¢ä¸­å¿?-> fall through
            default: return false;
        }
    }
    tag_t bodyTag = GetBodyFromSelection(objTag);
    if (bodyTag == NULL_TAG) return false;
    double minPt[3], maxPt[3];
    if (GetBodyGlobalBBox(bodyTag, minPt, maxPt) != 0) return false;
    double cx=(minPt[0]+maxPt[0])/2.0, cy=(minPt[1]+maxPt[1])/2.0, cz;
    if (isDest) { if (enumVal==5) enumVal=1; else if (enumVal==1) enumVal=3; else enumVal=1; }
    switch (enumVal) {
        case 0: cz=maxPt[2]; break;
        case 1: cz=(minPt[2]+maxPt[2])/2.0; break;
        case 2: cz=minPt[2]; break;
        case 3: {
            NXOpen::Body* b = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(bodyTag));
            double fc[3]={0,0,0}; int fcnt=0;
            if (b) {
                for (NXOpen::Face* f : b->GetFaces()) {
                    if (!f) continue;
                    double fx=0,fy=0,fz=0; int e=0;
                    for (NXOpen::Edge* ed : f->GetEdges()) {
                        if (!ed) continue;
                        NXOpen::Point3d ev1, ev2; ed->GetVertices(&ev1, &ev2); fx+=ev1.X+ev2.X;fy+=ev1.Y+ev2.Y;fz+=ev1.Z+ev2.Z;e+=2;
                    }
                    if (e>0) { fc[0]+=fx/e;fc[1]+=fy/e;fc[2]+=fz/e;fcnt++; }
                }
            }
            if (fcnt>0) { pt[0]=fc[0]/fcnt;pt[1]=fc[1]/fcnt;pt[2]=fc[2]/fcnt;return true; }
            cz=(minPt[2]+maxPt[2])/2.0; break;
        }
        default: cz=(minPt[2]+maxPt[2])/2.0; break;
    }
    pt[0]=cx;pt[1]=cy;pt[2]=cz;
    return true;
}

