//------------------------------------------------------------------------------
//Callback Name: update_cb
//------------------------------------------------------------------------------
int moveDlg::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    int errorCode = 0;
    try
    {
        if(block == button0) {
            tag_t objTag = GetFirstSelectedTag(theDialog,"selection0");
            if (objTag == NULL_TAG) { theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeError,"No object selected"); return 0; }
            NXOpen::Point3d srcPt(0,0,0), dstPt(0,0,0);
            if (point0SetByUser) { try { srcPt = point0->Point(); } catch(...) {} }
            else { double p[3]; if (CalculateEnumPoint(objTag, GetEnumValue(enum0), false, p)) srcPt = Point3d(p[0],p[1],p[2]); }
            if (point01SetByUser) { try { dstPt = point01->Point(); } catch(...) {} }
            else { double p[3]; if (CalculateEnumPoint(objTag, GetEnumValue(enum01), true, p)) dstPt = Point3d(p[0],p[1],p[2]); }
            if (MoveOrCopyObject(objTag, srcPt, dstPt, false))
                theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeInformation,"Completed");
            else
                theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeError,"Failed");
        }
        else if(block == button01) {
            tag_t objTag = GetFirstSelectedTag(theDialog,"selection0");
            if (objTag == NULL_TAG) { theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeError,"No object selected"); return 0; }
            NXOpen::Point3d srcPt(0,0,0), dstPt(0,0,0);
            if (point0SetByUser) { try { srcPt = point0->Point(); } catch(...) {} }
            else { double p[3]; if (CalculateEnumPoint(objTag, GetEnumValue(enum0), false, p)) srcPt = Point3d(p[0],p[1],p[2]); }
            if (point01SetByUser) { try { dstPt = point01->Point(); } catch(...) {} }
            else { double p[3]; if (CalculateEnumPoint(objTag, GetEnumValue(enum01), true, p)) dstPt = Point3d(p[0],p[1],p[2]); }
            if (MoveOrCopyObject(objTag, srcPt, dstPt, true))
                theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeInformation,"Completed");
            else
                theUI->NXMessageBox()->Show("moveDlg",NXOpen::NXMessageBox::DialogTypeError,"Failed");
        }
        else if(block == selection0) {}
        else if(block == point0) { point0SetByUser = true; }
        else if(block == enum0) {}
        else if(block == point01) { point01SetByUser = true; }
        else if(block == enum01) {}
    }
    catch(std::exception& ex) {
        moveDlg::theUI->NXMessageBox()->Show("Block Styler",NXOpen::NXMessageBox::DialogTypeError,ex.what());
        errorCode = 1;
    }
    return errorCode;
}
